// File: lighthouse-core/test/report/html/renderer/category-renderer-warnings-test.js
'use strict';

const assert = require('assert');
const fs = require('fs');
const jsdom = require('jsdom');
const Util = require('../../../../report/html/renderer/util.js');
const URL = require('../../../../lib/url-shim');
const DOM = require('../../../../report/html/renderer/dom.js');
const DetailsRenderer = require('../../../../report/html/renderer/details-renderer.js');
const CategoryRenderer = require('../../../../report/html/renderer/category-renderer.js');
const sampleResultsOrig = require('../../../results/sample_v2.json');

const TEMPLATE_FILE = fs.readFileSync(__dirname +
    '/../../../../report/html/templates.html', 'utf8');

describe('CategoryRenderer — passed audits warnings block', () => {
  let renderer;
  let sampleResults;

  beforeAll(() => {
    global.URL = URL;
    global.Util = Util;
    const {document} = new jsdom.JSDOM(TEMPLATE_FILE).window;
    const dom = new DOM(document);
    const detailsRenderer = new DetailsRenderer(dom);
    renderer = new CategoryRenderer(dom, detailsRenderer);
    sampleResults = Util.prepareReportResult(sampleResultsOrig);
  });

  afterAll(() => {
    global.URL = undefined;
    global.Util = undefined;
  });

  it('renders a consolidated warnings block below the passed audits', () => {
    // Pick a category and give all its passed audits some warnings
    const category = sampleResults.reportCategories.find(c => c.id === 'accessibility');
    category.auditRefs.forEach(ref => {
      if (ref.result.scoreDisplayMode === 'binary' && ref.result.score === 1) {
        // assign a couple of nested warning messages
        ref.result.warnings = [
          'Properly size images:',
          '  • Invalid image size information http://localhost/480-318.jpg',
          '  • Unable to decode /dobetterweb/someotherjpg.jpg'
        ];
      }
    });

    const categoryDOM = renderer.render(category, sampleResults.categoryGroups);
    const passedClump = categoryDOM.querySelector('.lh-clump--passed');
    assert.ok(passedClump, 'no passed audits clump rendered');

    // After the list of passed audits, there should be a single warnings block
    const warningsBlock = passedClump.querySelector('.lh-warnings') || passedClump.nextElementSibling;
    assert.ok(warningsBlock, 'did not render a warnings block after passed audits');
    assert.ok(warningsBlock.textContent.includes('Warnings:'), 'missing the "Warnings:" heading');
    assert.ok(warningsBlock.textContent.includes('Invalid image size information'), 'did not render first warning detail');
    assert.ok(warningsBlock.textContent.includes('Unable to decode'), 'did not render second warning detail');
  });
});
